public Query buildQueryForDebit(
    CustVendNettingPair _nettingPair,
    CurrencyCode _currencyCode,
    CustVendNettingRuleNettingSequence _sequence,
    boolean _isCreditDebitNote,
    NettingRuleProcessParameter _parameter)
{
    Query query = next buildQueryForDebit(_nettingPair, _currencyCode, _sequence, _isCreditDebitNote, _parameter);

    if (_sequence == CustVendNettingRuleNettingSequence::METByInvoiceNumber)
    {
        // Build a map of InvoiceId in the credit company
        TableId                 creditTable = tableNum(METNettingCustOpenTransView);
        Map                     invoiceMap  = new Map(Types::String, Types::Integer);
        Query                   creditQuery = new Query();
        QueryBuildDataSource    qbdsCredit  = creditQuery.addDataSource(creditTable);

        qbdsCredit.addRange(fieldName2Id(creditTable, 'AccountNum')).value(queryValue(_nettingPair.CreditAccountNum));
        //qbdsCredit.addRange(fieldName2Id(creditTable, 'CurrencyCode')).value(queryValue(_currencyCode));
        qbdsCredit.addRange(fieldNum(METNettingCustOpenTransView, LegalEntity)).value(queryValue(_nettingPair.CreditCompany));

        changecompany(_nettingPair.CreditCompany)
        {
            QueryRun qr = new QueryRun(creditQuery);
            while (qr.next())
            {
                Common  creditRecord    = qr.get(creditTable);
                str invoiceId           = creditRecord.getFieldValue('Invoice');

                if (invoiceId)
                {
                    invoiceMap.insert(invoiceId, 1);
                }
            }
        }

        // Add a range to the debit query for only matching InvoiceIds
        TableId                 debitTable = CustVendNettingRuleQueryBuilder::getDataSourceTableId(_nettingPair.DebitAccountType);
        QueryBuildDataSource    qbdsDebit = query.dataSourceNo(1);

        container       invoiceList;
        MapEnumerator   invoiceEnum = invoiceMap.getEnumerator();

        while (invoiceEnum.moveNext())
        {
            invoiceList += invoiceEnum.currentKey();
        }
        if (conLen(invoiceList) > 0)
        {
            qbdsDebit.addRange(fieldName2Id(debitTable, 'Invoice')).value(SysQuery::value(invoiceList));
        }
    }

    return query;
}

public Query buildQueryForCredit(CustVendNettingPair _nettingPair,
    CurrencyCode _currencyCode,
    CustVendNettingRuleNettingSequence _sequence,
    boolean _isCreditDebitNote,
    NettingRuleProcessParameter _parameter)
{
    Query query = next buildQueryForCredit(_nettingPair, _currencyCode, _sequence, _isCreditDebitNote, _parameter);

    if (_sequence == CustVendNettingRuleNettingSequence::METByInvoiceNumber)
    {
        // Build a map of InvoiceId in the debit company
        TableId                 debitTable = tableNum(METNettingVendTransOpenView);
        Map                     invoiceMap = new Map(Types::String, Types::Integer);
        Query                   debitQuery = new Query();
        QueryBuildDataSource    qbdsDebit  = debitQuery.addDataSource(debitTable);

        qbdsDebit.addRange(fieldName2Id(debitTable, 'AccountNum')).value(queryValue(_nettingPair.DebitAccountNum));
        //qbdsDebit.addRange(fieldName2Id(debitTable, 'CurrencyCode')).value(queryValue(_currencyCode));
        qbdsDebit.addRange(fieldNum(METNettingVendTransOpenView, LegalEntity)).value(queryValue(_nettingPair.DebitCompany));

        changecompany(_nettingPair.DebitCompany)
        {
            QueryRun qr = new QueryRun(debitQuery);

            while (qr.next())
            {
                Common  debitRecord = qr.get(debitTable);
                str     invoiceId   = debitRecord.getFieldValue('Invoice');

                if (invoiceId)
                {
                    invoiceMap.insert(invoiceId, 1);
                }
            }
        }

        // Add a range to the credit query for only matching InvoiceIds
        TableId                 creditTable = CustVendNettingRuleQueryBuilder::getDataSourceTableId(_nettingPair.CreditAccountType);
        QueryBuildDataSource    qbdsCredit = query.dataSourceNo(1);

        container       invoiceList;
        MapEnumerator   invoiceEnum = invoiceMap.getEnumerator();

        while (invoiceEnum.moveNext())
        {
            invoiceList += invoiceEnum.currentKey();
        }
        if (conLen(invoiceList) > 0)
        {
            qbdsCredit.addRange(fieldName2Id(creditTable, 'Invoice')).value(SysQuery::value(invoiceList));
        }
    }

    return query;
}

