public void applySequence(QueryBuildDataSource _qbds, TableId _dataSourceTableId, CustVendNettingRuleNettingSequence _sequence, boolean _isAmountPositive)
{
    next applySequence(_qbds, _dataSourceTableId, _sequence, _isAmountPositive);

    if (_sequence == CustVendNettingRuleNettingSequence::METByInvoiceNumber)
    {
        // Sort by InvoiceId ascending for Metcash custom sequence
        _qbds.addOrderByField(fieldName2Id(_dataSourceTableId, 'Invoice'));
    }
}
